 `curriculum` TEXT,\n  `price_start` TEXT,\n  `icon` TEXT,\n  `image` TEXT,\n  `badge` TEXT,\n  `order` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('1', 'weight-loss-fat-burn', 'Weight Loss & Body Transformation', 'Program penurunan berat badan intensif, pemangkasan lemak, & pembentukan lekuk tubuh ideal.', 'Pria & Wanita yang ingin turun berat badan 5–25 kg dengan aman tanpa efek rebound.', 'Program bimbingan privat 1-on-1 gabungan latihan HIIT, Strength Training, dan panduan kalori nutrition plan harian yang disesuaikan metabolisme tubuh Anda. Hasil terukur dengan InBody 3D Scan berkala.', '[\"Personal Trainer Privat 1-on-1 tersertifikasi APKI\",\"InBody 3D Scan Komposisi Tubuh Gratis Setiap 2 Minggu\",\"Custom Meal Plan & Panduan Defisit Kalori Harian\",\"Garansi Lingkar Pinggang & Lemak Tubuh Berkurang\",\"Jadwal Fleksibel (Pagi 06.00 s\\/d Malam 21.00 WIB)\"]', '[\"Membakar lemak membandel di perut, paha, dan lengan\",\"Meningkatkan metabolisme basal (BMR) agar tidak cepat gemuk\",\"Meningkatkan energi harian & stamina tubuh\",\"Membentuk postur tubuh lebih tegas & percaya diri\"]', '[\"Fase 1 (Minggu 1-2): Body Composition Assessment, Adaptasi Kardio & Corrective Exercise\",\"Fase 2 (Minggu 3-5): Fat Burn HIIT & Compound Movement Training (Squat, Deadlift, Bench)\",\"Fase 3 (Minggu 6-8): Metabolic Conditioning & Hypertrophy Sculpting\",\"Fase 4 (Minggu 9-12): Peak Transformation & Long-Term Maintenance System\"]', '450000', 'fire', 'images/assets/program_dewasa.webp', 'Paling Populer', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('2', 'muscle-building-hypertrophy', 'Muscle Building & Hypertrophy', 'Program pembentukan otot dada, bahu, lengan, & dada bidang untuk postur atletis.', 'Pria/Wanita yang ingin tambah massa otot, menaikkan berat badan bersih, & badan lebih berisi.', 'Dirancang untuk Anda yang ingin membangun otot secara proporsional dan efektif. Fokus pada Progressive Overload, form gerakan yang presisi, serta diet surplus nutrisi berprotein tinggi.', '[\"Privat Training dengan Metode Progressive Overload\",\"Evaluasi Form Gerakan & Biomekanika Otot\",\"Panduan Asupan Protein & Surplus Kalori Bersih\",\"Latihan Beban Free Weights & Machine Gym Modern\",\"Jadwal & Target Massa Otot Terukur Setiap Bulan\"]', '[\"Menambah berat badan sehat melalui pembentukan otot\",\"Menciptakan postur bahu lebar V-Taper & dada bidang\",\"Memperkuat kepadatan tulang & sendi tubuh\",\"Meningkatkan kadar testosterone alami & performa\"]', '[\"Minggu 1-2: Form Mastery & Neuromuscular Mind-Muscle Connection\",\"Minggu 3-6: Hypertrophy Split Routine (Push-Pull-Legs)\",\"Minggu 7-10: Heavy Compound Strength & Progressive Load\",\"Minggu 11-12: Muscle Peak & Symmetry Check\"]', '500000', 'dumbbell', 'images/assets/program_tni.webp', 'Rekomendasi Bulking', '2', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('3', 'female-fitness-shaping', 'Female Fitness & Body Shaping', 'Program gym privat khusus wanita: Kencangkan perut, bokong (Glutes), & membentuk lekuk tubuh.', 'Wanita / Muslimah yang menginginkan instruktur wanita & area gym privat yang nyaman.', 'Program kebugaran wanita modern yang memadukan Strength Training ringan, Pilates Mat, dan Glute-Focused Workouts. Dilatih oleh Personal Trainer wanita profesional.', '[\"100% Instruktur Trainer Wanita Berlisensi\",\"Area Studio Gym Privat Khusus Wanita (Bebas Riba & Safe Space)\",\"Latihan Glutes, Core, Lower Body & Toned Arms\",\"Panduan Nutrisi Hormonal & Bebas Diet Ketat Menyiksa\"]', '[\"Membentuk lekuk tubuh hourglass & mengencangkan bagian perut\",\"Menghilangkan gelambir lengan & paha dalam\",\"Menjaga keseimbangan hormon & metabolisme wanita\",\"Privasi 100% terjaga dengan suasana menyenangkan\"]', '[\"Tingkat 1: Full Body Mobility, Core Stabilization & Glute Activation\",\"Tingkat 2: Sculpting Lower Body & Tone Upper Body\",\"Tingkat 3: High Intensity Body Shaping & Pilates Core Fusion\"]', '480000', 'sparkles', 'images/assets/program_wanita.webp', '100% Trainer Wanita', '3', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('4', 'calisthenics-strength-conditioning', 'Strength & Conditioning / Persiapan Fisik TNI-POLRI', 'Program ketahanan fisik militer, latihan kalistenik, lari stamina, & pull-up maksimal.', 'Calon Taruna/Akpol, Bintara, POLRI, Kedinasan, & Atlet Performance.', 'Persiapan fisik komprehensif untuk mencapai standar tes Kesamaptaan Jasmani TNI-POLRI (Push-up, Sit-up, Pull-up, Shuttle Run, & Lari 12 Menit). Mentoring fisik ketat untuk nilai skor 100.', '[\"Simulasi Tes Kesamaptaan Standar Mabes TNI\\/POLRI\",\"Pelatihan Drill Pull-Up, Push-Up Presisi, & Shuttle Run\",\"Peningkatan Kapasitas Paru (VO2 Max) & Stamina Lari\",\"Evaluasi Video Biomekanika Gerakan Nilai Maksimal\",\"Pendampingan Nutrisi & Fisik Harian\"]', '[\"Memastikan lulus passing grade tinggi dengan nilai 100\",\"Meningkatkan daya tahan kardiovaskular & kekuatan otot\",\"Membentuk mental disiplin & pantang menyerah\"]', '[\"Minggu 1: Baseline Physical Diagnostic & Form Correction\",\"Minggu 2-4: Core Power, Calisthenics Progression & Pull-up Mastery\",\"Minggu 5-7: Speed & VO2 Max Interval Running Training\",\"Minggu 8: Trial Test Simulation & Peak Performance Readiness\"]', '550000', 'shield-check', 'images/assets/program_anak.webp', 'Garansi Skor Target', '4', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('5', 'posture-rehab-functional', 'Posture Correction & Rehab Fungsional', 'Pemulihan skoliosis, sakit pinggang (HNP/Saraf Kejepit), bahu bungkuk, & mobilitas sendi.', 'Pekerja kantoran, penderita bungkuk (Kyphosis), nyeri pinggang, & rehabilitasi cedera.', 'Program terapi latihan fungsional khusus untuk memperbaiki postur tubuh, menghilangkan rasa pegal kronis leher & punggung, serta memperkuat otot penopang tulang belakang.', '[\"Assesment Postur Tubuh & Mobilitas Sendi 3D\",\"Latihan Corrective Movement & Spinal Decompression\",\"Penanganan Kyphosis (Bahu Bungkuk) & Forward Head Posture\",\"Bimbingan Terapi Ringan Tanpa Risiko Cedera\"]', '[\"Menghilangkan nyeri punggung bawah (LBP) & saraf kejepit\",\"Memperbaiki postur berdiri & duduk agar tampak lebih tegap\",\"Meningkatkan fleksibilitas & kenyamanan gerak harian\"]', '[\"Fase 1: Pain Relief & Core Muscle Activation\",\"Fase 2: Spinal Realignment & Scapular Stabilization\",\"Fase 3: Functional Strength & Posture Maintenance\"]', '500000', 'heart-pulse', 'images/assets/program_terapi.webp', 'Rekomendasi Medis', '5', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `programs` (`id`, `slug`, `title`, `subtitle`, `target_audience`, `description`, `features`, `benefits`, `curriculum`, `price_start`, `icon`, `image`, `badge`, `order`, `created_at`, `updated_at`) VALUES ('6', 'corporate-wellness-group', 'Corporate Wellness & Group Fitness Class', 'Program kebugaran karyawan instansi, perusahaan, & kelas grup HIIT / Crossfit.', 'Perusahaan, instansi pemerintah, BUMN, sekolah, & komunitas fitness.', 'Paket pelatihan kebugaran kelompok untuk meningkatkan produktivitas karyawan, kesehatan fisik tim, dan ikatan kebersamaan perusahaan melalui kelas latihan seru.', '[\"Tim Personal Trainer Complete membawa peralatan\",\"Medical & Physical Checkup Karyawan Berkala\",\"Pilihan Kelas: HIIT Functional, Yoga BootCamp, Zumba\\/Crossfit\",\"Diskon Khusus Rombongan Instansi\"]', '[\"Menurunkan angka sakit karyawan & meningkatkan stamina kerja\",\"Membangun budaya kerja sehat & kekompakan tim (Team Building)\",\"Sesi interaktif yang menyenangkan & membakar kalori tinggi\"]', '[\"Sesi 1: Health Assessment & Group Warmup BootCamp\",\"Sesi 2-4: Functional Group Challenge & Cardio Burn Class\"]', '1500000', 'users-three', 'images/assets/program_privat.webp', 'Paket Rombongan', '6', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `coaches`;\nCREATE TABLE `coaches` (\n  `id` TEXT,\n  `name` TEXT,\n  `title` TEXT,\n  `specialty` TEXT,\n  `description` TEXT,\n  `photo` TEXT,\n  `color` TEXT,\n  `order` TEXT,\n  `is_active` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `coaches` (`id`, `name`, `title`, `specialty`, `description`, `photo`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'Coach Hendra', 'S.Or, CSCS', 'Head PT & Weight Loss Specialist', 'Lulusan Ilmu Keolahragaan UNY & APKI Certified. Pengalaman 10+ tahun melatih 500+ member fat burn & body transformation.', 'images/assets/coach_hendra.webp', '#10b981', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `coaches` (`id`, `name`, `title`, `specialty`, `description`, `photo`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'Coach Danu', 'APKI Certified', 'Persiapan TNI/POLRI & Muscle Building', 'Mantan instruktur fisik militer. Spesialis drill kalistenik, stamina lari 12 menit, & pull-up presisi nilai 100.', 'images/assets/coach_danu.webp', '#f97316', '2', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `coaches` (`id`, `name`, `title`, `specialty`, `description`, `photo`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'Coach Rina', 'Pilates & Female Fitness Specialist', 'Female Body Shaping & Glute Workout', 'Personal Trainer wanita khusus member cewek & muslimah. Penguasaan Reformer Pilates & shaping lekuk tubuh.', 'images/assets/coach_rina.webp', '#ec4899', '3', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `coaches` (`id`, `name`, `title`, `specialty`, `description`, `photo`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'Coach Bima', 'S.Fis, AIFO', 'Posture Rehab & Pain Relief', 'Fisioterapis keolahragaan. Spesialis penanganan bungkuk (Kyphosis), scoliosis ringan, & rehabilitasi pasca cedera.', 'images/assets/coach_bima.webp', '#38bdf8', '4', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `posts`;\nCREATE TABLE `posts` (\n  `id` TEXT,\n  `slug` TEXT,\n  `title` TEXT,\n  `category` TEXT,\n  `excerpt` TEXT,\n  `content` TEXT,\n  `image` TEXT,\n  `author` TEXT,\n  `reading_time` TEXT,\n  `views` TEXT,\n  `published_at` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `posts` (`id`, `slug`, `title`, `category`, `excerpt`, `content`, `image`, `author`, `reading_time`, `views`, `published_at`, `created_at`, `updated_at`) VALUES ('1', 'panduan-lengkap-defisit-kalori-dan-latihan-beban-penurunan-berat-badan', 'Panduan Lengkap Defisit Kalori & Latihan Beban: Rahasia Turun BB Tanpa Efek Yoyo', 'Nutrisi & Fat Loss', 'Ingin menurunkan lemak tubuh secara permanent tanpa harus kelaparan? Pahami sains di balik perhitungan BMR, defisit kalori bersih, dan pentingnya latihan beban.', '<p>Banyak orang terjebak dalam diet ekstrem hanya makan buah atau melakukan kardio berlebihan jam-jaman. Padahal kunci sukses pemangkasan lemak jangka panjang adalah kombinasi <strong>Defisit Kalori Terukur + Latihan Beban (Strength Training)</strong>.</p><h3>1. Hitung BMR & TDEE Anda</h3><p>Basal Metabolic Rate (BMR) adalah jumlah kalori yang dibakar tubuh saat beristirahat. Untuk memangkas lemak 0.5 kg per minggu, buatlah defisit 300–500 kalori dari TDEE Anda.</p><h3>2. Utamakan Asupan Protein Tinggi</h3><p>Konsumsi protein 1.6 - 2.2 gram per kg berat badan untuk mencegah otot terkikis saat proses pembakaran lemak berlangsung.</p><h3>3. Latihan Beban Jaga Massa Otot</h3><p>Otot yang terlatih memikat metabolisme tubuh agar tetap aktif membakar kalori bahkan saat Anda sedang tidur nyenyak.</p>', 'images/assets/program_dewasa.webp', 'Coach Hendra, CSCS', '5', '0', '2026-08-08 11:52:01', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `posts` (`id`, `slug`, `title`, `category`, `excerpt`, `content`, `image`, `author`, `reading_time`, `views`, `published_at`, `created_at`, `updated_at`) VALUES ('2', '5-kesalahan-fatal-pemula-saat-pertama-kali-latihan-di-gym', '5 Kesalahan Fatal Pemula Saat Pertama Kali Gym & Cara Menghindarnya', 'Tips Fitness', 'Baru mau mulai gym? Hindari ego lifting, abaikan pemanasan, atau form gerakan salah yang dapat memicu cedera sendi dan menghentikan progress Anda.', '<p>Memulai perjalanan kebugaran di gym adalah keputusan luar biasa. Namun, pastikan Anda menghindari 5 kesalahan umum berikut:</p><h3>1. Ego Lifting (Beban Terlalu Berat)</h3><p>Fokuslah pada teknik form gerakan yang benar terlebih dahulu sebelum menambah beban piringan berat.</p><h3>2. Melewatkan Pemanasan Dinamis</h3><p>Pemanasan sendi dan otot selama 5–10 menit sangat vital untuk melumasi cairan sinovial sendi dan mencegah kram.</p><h3>3. Tidak Memiliki Program Latihan Terstruktur</h3><p>Jangan asal mencoba alat tanpa rencana. Pakailah program split routine yang teruji seperti Push-Pull-Legs.</p>', 'images/assets/program_tni.webp', 'Coach Danu, APKI Certified', '4', '0', '2026-08-08 11:52:01', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `posts` (`id`, `slug`, `title`, `category`, `excerpt`, `content`, `image`, `author`, `reading_time`, `views`, `published_at`, `created_at`, `updated_at`) VALUES ('3', 'rahasia-pull-up-20x-presisi-persiapan-tes-kesamaptaan-tni-polri', 'Rahasia Tembus Pull-Up 20x Presisi untuk Tes Kesamaptaan TNI & POLRI', 'Persiapan TNI', 'Kesulitan menaikkan jumlah pull-up? Pelajari teknik penguatan otot Lats, bicep grip, dan latihan negatif pull-up untuk hasil skor maksimal 100.', '<p>Pull-up merupakan tes fisik tersulit bagi banyak peserta calon Bintara dan Taruna. Untuk menguasainya, Anda butuh latihan spesifik berikut:</p><h3>1. Latihan Negative Pull-Up</h3><p>Melompat ke atas bar lalu menahan tubuh turun perlahan selama 5 detik. Ini membangun kekuatan otot dasar dengan cepat.</p><h3>2. Kuatkan Otot Core & Lats</h3><p>Pull-up bukan hanya tentang otot lengan, tetapi pelibatan otot punggung Latissimus Dorsi dan ayunan tubuh yang stabil.</p>', 'images/assets/program_anak.webp', 'Coach Serka (Purn) Danu', '6', '0', '2026-08-08 11:52:01', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `posts` (`id`, `slug`, `title`, `category`, `excerpt`, `content`, `image`, `author`, `reading_time`, `views`, `published_at`, `created_at`, `updated_at`) VALUES ('4', 'manfaat-latihan-beban-bagi-wanita-mengencangkan-tubuh-dan-cegah-osteoporosis', 'Manfaat Luar Biasa Latihan Beban bagi Wanita: Tubuh Ramping, Kencang & Bebas Osteoporosis', 'Female Fitness', 'Benarkah angkat beban bikin wanita berotot besar? Simak penjelasan ilmiah mengapa angkat beban adalah kunci utama lekuk tubuh ideal wanita.', '<p>Banyak wanita khawatir angkat beban akan membuat tubuh kekar bak binaragawan. Hal ini adalah salah kaprah. Hormon estrogen pada wanita membuat tubuh merespons latihan beban dengan bentuk yang ramping, kencang, dan proporsional.</p>', 'images/assets/program_wanita.webp', 'Coach Rina, Pilates & Strength Specialist', '4', '0', '2026-08-08 11:52:01', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `testimonials`;\nCREATE TABLE `testimonials` (\n  `id` TEXT,\n  `name` TEXT,\n  `role` TEXT,\n  `program` TEXT,\n  `rating` TEXT,\n  `review` TEXT,\n  `avatar` TEXT,\n  `video_url` TEXT,\n  `is_featured` TEXT,\n  `is_approved` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `testimonials` (`id`, `name`, `role`, `program`, `rating`, `review`, `avatar`, `video_url`, `is_featured`, `is_approved`, `created_at`, `updated_at`) VALUES ('1', 'Bima Perkasa (28 th)', 'Software Engineer (Sleman)', 'Weight Loss & Body Transformation', '5', 'Turun 16 kg dalam 3 bulan! Dulu sering sakit pinggang karena kelamaan duduk koding & BB 88 kg. Dibimbing Coach ApexFitness dengan pola latihan intensif tapi tetep bisa makan nasi. Sekarang BB 72 kg & perut buncit hilang!', 'images/assets/coach_hendra.webp', 'https://www.youtube.com/embed/5ee8sX_1-9c', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `testimonials` (`id`, `name`, `role`, `program`, `rating`, `review`, `avatar`, `video_url`, `is_featured`, `is_approved`, `created_at`, `updated_at`) VALUES ('2', 'Rian Ardianto', 'Lulusan Bintara POLRI 2026', 'Strength & Persiapan TNI-POLRI', '5', 'Awalnya pull-up cuma bisa 3x dan lari 12 menit dapet 1800m. Setelah 2 bulan gabung ApexFitness program TNI-POLRI, pull-up tembus 18x presisi & lari tembus 3100m. Nilai kesamaptaan saya dapet 100 sempurna!', 'images/assets/coach_danu.webp', 'https://www.youtube.com/embed/xVeXGKPOH58', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `testimonials` (`id`, `name`, `role`, `program`, `rating`, `review`, `avatar`, `video_url`, `is_featured`, `is_approved`, `created_at`, `updated_at`) VALUES ('3', 'Anisa Rahma, S.Farm', 'Apoteker & Member Wanita', 'Female Fitness & Body Shaping', '5', 'Privasi luar biasa nyaman karena ada area khusus cewek & pelatih wanita yang ramah. Dalam 8 minggu paha & pinggul jadi kencang, lengan tidak gelambir lagi. Berat badan ideal & badan terasa super fit!', 'images/assets/coach_rina.webp', 'https://www.youtube.com/embed/M5cs8a3Bhfg', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `testimonials` (`id`, `name`, `role`, `program`, `rating`, `review`, `avatar`, `video_url`, `is_featured`, `is_approved`, `created_at`, `updated_at`) VALUES ('4', 'Drs. Supriyanto (49 th)', 'PNS & Pasien Posture Rehab', 'Posture Correction & Rehab', '5', 'Nyeri saraf kejepit di pinggang bawah yang mengganggu tidur selama 2 tahun akhirnya sembuh total setelah terapi latihan fungsional di ApexFitness. Postur berdiri jadi tegap & rasa pegal hilang.', 'images/assets/coach_bima.webp', NULL, '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `faqs`;\nCREATE TABLE `faqs` (\n  `id` TEXT,\n  `category` TEXT,\n  `question` TEXT,\n  `answer` TEXT,\n  `is_popular` TEXT,\n  `order` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('1', 'Umum', 'Mengapa harus latihan bersama Personal Trainer di ApexFitness?', 'ApexFitness didukung oleh tim Personal Trainer tersertifikasi APKI & IFBB dengan rekam jejak sukses melatih 1000+ member. Kami menyediakan program yang disesuaikan 100% dengan kondisi fisik Anda, evaluasi InBody 3D Scan, serta panduan nutrisi harian.', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('2', 'Umum', 'Berapa lama waktu yang dibutuhkan sampai hasil terlihat?', 'Dengan mengikuti sesi PT 3x seminggu dan mematuhi panduan nutrisi, perubahan fisik awal (penurunan berat badan 2–4 kg atau peningkatan tonus otot) dapat terlihat dan terasa dalam 3–4 minggu pertama.', '1', '2', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('3', 'Umum', 'Saya pemula dan belum pernah ke gym, apakah bisa?', 'Sangat bisa! 70% member ApexFitness adalah pemula yang baru pertama kali menyentuh alat gym. Trainer kami akan membimbing secara perlahan dari pengenalan alat, form gerakan yang aman, hingga peningkatan beban bertahap.', '1', '3', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('4', 'Umum', 'Apakah ada garansi penurunan berat badan atau pembentukan otot?', 'Ya! Kami memberikan garansi bimbingan tambahan bagi peserta program komitmen yang menjalankan saran trainer & nutrisi namun belum mencapai target yang disepakati.', '0', '4', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('5', 'Personal Training', 'Bagaimana cara klaim Free Trial Sesi 1 Personal Trainer?', 'Anda cukup mengisi formulir daftar trial di website ini atau klik tombol WhatsApp Admin. Tim kami akan menjadwalkan sesi trial gratis 45 menit meliputi Body Assessment + Sesi Latihan Privat.', '1', '5', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('6', 'Personal Training', 'Apakah ada Personal Trainer wanita khusus member perempuan?', 'Tentu saja ada! Kami memiliki tim Personal Trainer wanita berpengalaman khusus untuk member wanita/muslimah yang menginginkan kenyamanan dan privasi tinggi.', '1', '6', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('7', 'Personal Training', 'Bagaimana jika jadwal saya berubah-ubah karena pekerjaan?', 'Jadwal latihan di ApexFitness super fleksibel. Anda dapat berkoordinasi langsung dengan Trainer pribadi Anda untuk menentukan jam latihan harian dari pukul 06.00 hingga 21.00 WIB.', '0', '7', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('8', 'Personal Training', 'Apakah saya mendapat panduan makanan / Diet Plan?', 'Ya, setiap paket PT sudah termasuk fasilitas Custom Meal Plan harian berdasarkan kebutuhan kalori makro (Protein, Karbohidrat, Lemak) yang disesuaikan dengan makanan kesukaan Anda.', '0', '8', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('9', 'Fasilitas & Gym', 'Peralatan apa saja yang tersedia di cabang ApexFitness?', 'Fasilitas kami dilengkapi alat strength impor kelas dunia (Hammer Strength, LifeFitness), area free weights lengkap, kardio zone (Treadmill, Assault Bike), studio kelas, locker room, shower air hangat, dan InBody Scan.', '0', '9', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('10', 'Fasilitas & Gym', 'Apakah bisa Personal Trainer datang ke rumah / gym perumahan (Home PT)?', 'Bisa. Kami melayani program Private Home Personal Training di wilayah Yogyakarta dan sekitarnya. Trainer kami akan membawa peralatan pendukung ke lokasi Anda.', '1', '10', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('11', 'Kesehatan & Rehab', 'Saya memiliki masalah nyeri pinggang / saraf kejepit, apakah aman ikut gym?', 'Sangat aman jika dibimbing trainer spesialis rehab. Program Posture Correction & Rehab kami berfokus pada dekompresi tulang belakang, peregangan otot tegang, dan penguatan otot core penopang tubuh.', '1', '11', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('12', 'Kesehatan & Rehab', 'Apakah wanita yang latihan beban tubuhnya akan menjadi kekar seperti pria?', 'Tidak! Mitos wanita kekar karena angkat beban adalah tidak benar. Secara biologis kadar hormon testosterone wanita jauh lebih rendah dari pria. Latihan beban pada wanita akan membentuk tubuh lebih ramping, kencang, dan berbentuk indah.', '0', '12', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('13', 'Persiapan TNI/POLRI', 'Bagaimana metode latihan fisik untuk persiapan tes TNI/POLRI?', 'Program difokuskan pada peningkatan jumlah repetisi Pull-Up presisi, Push-Up standar Mabes, Sit-Up, Shuttle Run cepat, dan daya tahan lari 12 menit dengan pacing yang efisien.', '1', '13', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('14', 'Pembayaran & Paket', 'Metode pembayaran apa saja yang diterima?', 'Kami menerima pembayaran Cash, Transfer Bank, QRIS, serta Cicilan 0% via Kartu Kredit / E-Wallet untuk paket membership tahunan dan paket PT.', '0', '14', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('15', 'Pembayaran & Paket', 'Apakah ada promo diskon jika daftar berdua dengan pasangan / teman?', 'Ada! Kami menyediakan Promo Couple & Buddy Package dengan diskon hingga 20% untuk pendaftaran 2 orang sekaligus.', '1', '15', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_popular`, `order`, `created_at`, `updated_at`) VALUES ('16', 'Pembayaran & Paket', 'Berapa masa berlaku paket pertemuan Sesi PT?', 'Paket 12 sesi memiliki masa aktif 2 bulan, sedangkan paket 24–48 sesi memiliki masa aktif hingga 6 bulan dengan toleransi pembekuan (cuti latihan) jika Anda bertugas luar kota.', '0', '16', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `videos`;\nCREATE TABLE `videos` (\n  `id` TEXT,\n  `title` TEXT,\n  `subtitle` TEXT,\n  `before_badge` TEXT,\n  `after_badge` TEXT,\n  `description` TEXT,\n  `video_url` TEXT,\n  `thumbnail` TEXT,\n  `order` TEXT,\n  `is_active` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `videos` (`id`, `title`, `subtitle`, `before_badge`, `after_badge`, `description`, `video_url`, `thumbnail`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'Bima (28 Tahun)', 'Hari 1: 88 kg & Perut Buncit ➔ Hari 90: 72 kg Lean Muscle', '🔴 Hari 1: 88 kg Fat', '🟢 Hari 90: 72 kg Lean', 'Transformasi total 16 kg lemak terpangkas dalam 90 hari bimbingan privat Personal Trainer ApexFitness & custom diet plan!', 'https://www.youtube.com/embed/5ee8sX_1-9c', 'images/assets/video_thumb_daffa.png', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `videos` (`id`, `title`, `subtitle`, `before_badge`, `after_badge`, `description`, `video_url`, `thumbnail`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'Anisa (25 Tahun)', 'Bulan 1: Posture Bungkuk ➔ Bulan 3: Hourglass Shape & Toned Body', '🔴 Bulan 1: Gelambir & Bungkuk', '🟢 Bulan 3: Hourglass', 'Bimbingan Personal Trainer wanita 1-on-1. Membentuk lekuk pinggul, mengencangkan paha & memperbaiki postur tegap!', 'https://www.youtube.com/embed/M5cs8a3Bhfg', 'images/assets/video_thumb_siti.png', '2', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `videos` (`id`, `title`, `subtitle`, `before_badge`, `after_badge`, `description`, `video_url`, `thumbnail`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'Rian (Calon TNI/POLRI)', 'Hari 1: Pull-up 3x & Lari 1800m ➔ Hari 60: Pull-up 18x & Lari 3100m', '🔴 Hari 1: Skor 40', '🟢 Hari 60: Lulus 100', 'Pelatihan stamina fisik & kekuatan kalistenik intensif. Lulus tes kesamaptaan jasmani dengan nilai sempurna 100!', 'https://www.youtube.com/embed/xVeXGKPOH58', 'images/assets/video_thumb_rian.png', '3', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\nDROP TABLE IF EXISTS `features`;\nCREATE TABLE `features` (\n  `id` TEXT,\n  `icon` TEXT,\n  `title` TEXT,\n  `description` TEXT,\n  `color` TEXT,\n  `order` TEXT,\n  `is_active` TEXT,\n  `created_at` TEXT,\n  `updated_at` TEXT,\n  PRIMARY KEY (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n\nINSERT INTO `features` (`id`, `icon`, `title`, `description`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('1', 'fa-solid fa-certificate', 'Trainer Berlisensi APKI / IFBB', 'Didampingi Personal Trainer profesional tersertifikasi nasional & internasional yang berpengalaman melatih 1000+ member.', '#10b981', '1', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `features` (`id`, `icon`, `title`, `description`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('2', 'fa-solid fa-chart-line', 'InBody 3D Scan & Body Assessment', 'Evaluasi massa otot, % lemak tubuh, dan kadar metabolisme tubuh secara akurat setiap 2 minggu sekali.', '#f97316', '2', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `features` (`id`, `icon`, `title`, `description`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'fa-solid fa-person-dress', 'Trainer Wanita & Studio Privat', 'Khusus member wanita / muslimah dengan Personal Trainer wanita sabar & area studio gym privat aman 100%.', '#ec4899', '3', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\nINSERT INTO `features` (`id`, `icon`, `title`, `description`, `color`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('4', 'fa-solid fa-trophy', 'Garansi Hasil Terukur', 'Program latihan terstruktur, custom meal plan harian, & garansi pemangkasan lemak/pembentukan otot progresif.', '#38bdf8', '4', '1', '2026-08-08 11:52:01', '2026-08-08 11:52:01');\n\n